-- Generated by scripts/build_bootstrap.py; one transaction, no data reset.
BEGIN;
-- 20261016000100_trading.sql
-- Run as database owner, not with a Data API key. No existing application data is deleted.
create schema if not exists bot_private;
revoke all on schema bot_private from public, anon, authenticated;

create table if not exists bot_private.accounts (
  id text primary key check (id ~ '^[a-z][a-z0-9-]{2,63}$'),
  is_test boolean not null,
  version bigint not null default 0 check (version >= 0),
  value jsonb,
  initial_jpy numeric check (initial_jpy = 1000000),
  created_at timestamptz,
  last_event_at timestamptz,
  status text not null default 'PREPARING' check (status in ('PREPARING','ACTIVE','PAUSED')),
  check (is_test = (id like 'test-%'))
);
create table if not exists bot_private.balances (
  account_id text references bot_private.accounts(id) on delete cascade,
  currency text check (currency in ('JPY','USD')),
  amount numeric not null check (amount >= 0 and amount <> 'NaN'::numeric),
  primary key(account_id,currency),
  check (amount = trunc(amount, case when currency='JPY' then 0 else 2 end))
);
create table if not exists bot_private.positions (
  account_id text references bot_private.accounts(id) on delete cascade,
  symbol text,
  market text not null check (market in ('JP','US')),
  currency text not null check (currency in ('JPY','USD')),
  quantity bigint not null check (quantity >= 0),
  average_cost numeric not null check (average_cost >= 0 and average_cost <> 'NaN'::numeric),
  cost_basis numeric not null check (cost_basis >= 0 and cost_basis <> 'NaN'::numeric),
  updated_at timestamptz not null,
  primary key(account_id,symbol),
  check ((market='JP') = (currency='JPY'))
);
-- Event payloads preserve the existing Pydantic contracts without duplicating accounting.
-- Financial fields are also NUMERIC, never IEEE float. Prices are NOT exposed publicly.
create table if not exists bot_private.records (
  account_id text references bot_private.accounts(id) on delete cascade,
  kind text check (kind in ('orders','executions','fx_exchanges','cash_ledger','valuations',
    'decisions','api_usage','benchmark_prices','benchmark_investments','snapshots',
    'snapshot_revisions','dashboard')),
  key text not null check (length(key) between 1 and 256),
  payload jsonb not null check (jsonb_typeof(payload)='object'),
  seq bigint generated always as identity unique,
  amount numeric generated always as ((payload->>'amount')::numeric) stored,
  price numeric generated always as ((payload->>'price')::numeric) stored,
  notional numeric generated always as ((payload->>'notional')::numeric) stored,
  commission numeric generated always as ((payload->>'commission')::numeric) stored,
  usd_jpy numeric generated always as ((payload->>'usd_jpy')::numeric) stored,
  nav_jpy numeric generated always as ((payload->>'nav_jpy')::numeric) stored,
  total_jpy numeric generated always as ((payload->>'total_jpy')::numeric) stored,
  source_amount numeric generated always as ((payload->>'source_amount')::numeric) stored,
  received_amount numeric generated always as ((payload->>'received_amount')::numeric) stored,
  realized_pnl numeric generated always as (
    case when kind='executions' then (payload->>'realized_pnl')::numeric end) stored,
  quantity bigint generated always as ((payload->>'quantity')::bigint) stored,
  order_id text generated always as (case when kind='executions' then payload->>'order_id' end) stored,
  order_kind text generated always as (case when kind='executions' then 'orders' end) stored,
  primary key(account_id,kind,key),
  foreign key(account_id,order_kind,order_id) references bot_private.records(account_id,kind,key)
    deferrable initially deferred,
  check (price is null or (price > 0 and price <> 'NaN'::numeric)),
  check (notional is null or (notional >= 0 and notional <> 'NaN'::numeric)),
  check (commission is null or (commission >= 0 and commission <> 'NaN'::numeric)),
  check (usd_jpy is null or (usd_jpy > 0 and usd_jpy <> 'NaN'::numeric)),
  check (quantity is null or quantity > 0),
  check (kind not in ('orders','executions') or payload ?& array['symbol','side','quantity','currency']),
  check (kind <> 'orders' or (payload ?& array['status','order_id','requested_at'] and payload->>'status' in ('PENDING','FILLED','REJECTED','CANCELLED')
    and payload->>'side' in ('BUY','SELL') and payload->>'order_id'=key)),
  check (kind <> 'api_usage' or (payload ?& array['status','request_id','at','model','decision_id']
    and payload->>'status' in ('RESERVED','SUCCESS','ERROR'))),
  check (kind <> 'decisions' or payload->>'status' in ('RUNNING','SUCCESS','REGISTERED','FAILED')),
  check (kind <> 'cash_ledger' or (payload->>'balance_after')::numeric >= 0)
);
create index if not exists bot_usage on bot_private.records(kind,(payload->>'at'))
  where kind='api_usage';
alter table bot_private.accounts enable row level security;
alter table bot_private.balances enable row level security;
alter table bot_private.positions enable row level security;
alter table bot_private.records enable row level security;
revoke all on all tables in schema bot_private from public,anon,authenticated,service_role;

create or replace function public.bot_read(p_account text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'version',coalesce((select version from bot_private.accounts where id=p_account),0),
    'account',(select value from bot_private.accounts where id=p_account),
    'records',coalesce((select jsonb_agg(jsonb_build_object('kind',kind,'key',key,'payload',payload)
      order by seq) from bot_private.records where account_id=p_account),'[]'::jsonb))
$$;

create or replace function public.bot_commit(
  p_account text, p_test boolean, p_version bigint, p_value jsonb, p_writes jsonb
) returns bigint language plpgsql security definer set search_path = '' as $$
declare a bot_private.accounts; item jsonb; old jsonb; v jsonb; c text; q numeric;
begin
  -- A small research bot: serialize writers globally, then compare account version.
  -- Quota reservations acquire the SAME lock; no cross-account quota races/deadlocks.
  perform pg_advisory_xact_lock(490016001);
  insert into bot_private.accounts(id,is_test) values(p_account,p_test) on conflict do nothing;
  select * into a from bot_private.accounts where id=p_account for update;
  if a.version <> p_version then
    raise exception using errcode='40001', message='version conflict';
  end if;
  if a.is_test <> p_test or p_value is null or jsonb_typeof(p_writes)<>'array' then
    raise exception 'invalid account scope or state';
  end if;
  if a.value is not null and (
    a.value->'created_at' is distinct from p_value->'created_at' or
    a.value->'initial_jpy' is distinct from p_value->'initial_jpy' or
    coalesce((p_value->>'last_event_at')::timestamptz,(p_value->>'created_at')::timestamptz)
      < coalesce(a.last_event_at,a.created_at)
  ) then raise exception 'account reset or time reversal forbidden'; end if;
  if (p_value->>'initial_jpy')::numeric <> 1000000 or p_value->>'account_id'<>'paper' then
    raise exception 'invalid initial capital';
  end if;
  for item in select * from jsonb_array_elements(p_writes) loop
    v := item->'payload';
    select payload into old from bot_private.records
      where account_id=p_account and kind=item->>'kind' and key=item->>'key';
    if old is not null then
      if item->>'kind' not in ('orders','decisions','api_usage','snapshots','dashboard') then
        raise exception 'append-only event';
      end if;
      if item->>'kind'='orders' and (
        (old-'status'-'reason') is distinct from (v-'status'-'reason') or
        (old->>'status'<>'PENDING' and old is distinct from v)
      ) then raise exception 'illegal order transition'; end if;
      if item->>'kind'='decisions' and (
        (old->>'status' in ('FAILED','REGISTERED') and old is distinct from v) or
        (old->>'status'='SUCCESS' and v->>'status' not in ('SUCCESS','REGISTERED'))
      ) then raise exception 'illegal decision transition'; end if;
      if item->>'kind'='api_usage' and (
        old->>'status'<>'RESERVED' or
        (old->>'at')::timestamptz <> (v->>'at')::timestamptz or
        (old-'at'-'status'-'input_tokens'-'output_tokens'-'total_tokens'-'thought_tokens'-'error'
          -'http_status'-'estimated_cost_usd') is distinct from
        (v-'at'-'status'-'input_tokens'-'output_tokens'-'total_tokens'-'thought_tokens'-'error'
          -'http_status'-'estimated_cost_usd')
      ) then raise exception 'illegal quota transition'; end if;
    elsif item->>'kind'='api_usage' then
      raise exception 'use quota reservation RPC';
    end if;
    insert into bot_private.records(account_id,kind,key,payload)
      values(p_account,item->>'kind',item->>'key',v)
      on conflict(account_id,kind,key) do update set payload=excluded.payload;
  end loop;
  delete from bot_private.balances where account_id=p_account;
  foreach c in array array['JPY','USD'] loop
    q := (p_value->'balances'->>c)::numeric;
    if q is null then raise exception 'missing currency'; end if;
    -- Reconcile the common Python ledger inside the very same DB transaction.
    if q <> coalesce((select sum(amount) from bot_private.records
      where account_id=p_account and kind='cash_ledger' and payload->>'currency'=c),0) then
      raise exception 'cash ledger does not reconcile';
    end if;
    insert into bot_private.balances values(p_account,c,q);
  end loop;
  delete from bot_private.positions where account_id=p_account;
  for item in select value from jsonb_each(p_value->'positions') loop
    q := coalesce((select sum(case when payload->>'side'='BUY' then quantity else -quantity end)
      from bot_private.records where account_id=p_account and kind='executions'
        and payload->>'symbol'=item->'instrument'->>'symbol'),0);
    if q <> (item->>'quantity')::bigint then raise exception 'position does not reconcile'; end if;
    insert into bot_private.positions values(p_account,item->'instrument'->>'symbol',
      item->'instrument'->>'market',item->'instrument'->>'currency',(item->>'quantity')::bigint,
      (item->>'average_cost')::numeric,(item->>'cost_basis')::numeric,now());
  end loop;
  if exists(select 1 from (
    select payload->>'symbol' symbol,
      sum(case when payload->>'side'='BUY' then quantity else -quantity end) shares,
      sum(case when payload->>'side'='BUY' then notional+commission
          else -(notional-commission-(payload->>'realized_pnl')::numeric) end) basis
    from bot_private.records where account_id=p_account and kind='executions'
    group by payload->>'symbol'
  ) e left join bot_private.positions p on p.account_id=p_account and p.symbol=e.symbol
    where e.shares<>coalesce(p.quantity,0) or e.basis<>coalesce(p.cost_basis,0)) then
    raise exception 'execution positions or cost basis do not reconcile';
  end if;
  if exists(select 1 from bot_private.records e left join bot_private.records o
    on o.account_id=e.account_id and o.kind='orders' and o.key=e.order_id
    where e.account_id=p_account and e.kind='executions' and
    (o.key is null or o.payload->>'status'<>'FILLED' or e.quantity<>o.quantity
      or e.payload->>'side'<>o.payload->>'side' or e.payload->>'symbol'<>o.payload->>'symbol'))
  or exists(select 1 from bot_private.records o where o.account_id=p_account and o.kind='orders'
    and o.payload->>'status'='FILLED' and not exists(select 1 from bot_private.records e
      where e.account_id=p_account and e.kind='executions' and e.order_id=o.key)) then
    raise exception 'order execution mismatch';
  end if;
  update bot_private.accounts set value=p_value, version=version+1,
    initial_jpy=(p_value->>'initial_jpy')::numeric,created_at=(p_value->>'created_at')::timestamptz,
    last_event_at=(p_value->>'last_event_at')::timestamptz where id=p_account;
  return a.version+1;
end $$;

create or replace function public.bot_reserve_api(
  p_account text,p_decision text,p_request text,p_model text,
  p_day_limit integer,p_month_limit integer,p_run_limit integer
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare day_count bigint; month_count bigint; run_count bigint; v jsonb; t timestamptz:=now();
begin
  perform pg_advisory_xact_lock(490016001);
  if not exists(select 1 from bot_private.records where account_id=p_account
    and kind='decisions' and key=p_decision and payload->>'status'='RUNNING') then
    raise exception 'running decision required';
  end if;
  select count(*) filter(where (payload->>'at')::timestamptz >=
      date_trunc('day',t at time zone 'UTC') at time zone 'UTC'), count(*)
    into day_count,month_count from bot_private.records
    where kind='api_usage' and (payload->>'at')::timestamptz >=
      date_trunc('month',t at time zone 'UTC') at time zone 'UTC';
  select count(*) into run_count from bot_private.records where account_id=p_account
    and kind='api_usage' and payload->>'decision_id'=p_decision;
  if p_day_limit<0 or p_month_limit<0 or p_run_limit not between 1 and 5 or
    day_count>=p_day_limit or month_count>=p_month_limit or run_count>=p_run_limit then
    raise exception 'shared API quota exhausted';
  end if;
  v:=jsonb_build_object('request_id',p_request,'decision_id',p_decision,'at',t,
    'model',p_model,'status','RESERVED');
  insert into bot_private.records(account_id,kind,key,payload) values(p_account,'api_usage',p_request,v);
  update bot_private.accounts set version=version+1 where id=p_account;
  return v;
end $$;

create or replace function public.bot_delete_test(p_account text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  perform pg_advisory_xact_lock(490016001);
  if p_account not like 'test-%' or not exists(select 1 from bot_private.accounts
    where id=p_account and is_test) then raise exception 'test account required'; end if;
  -- Retain consumed global quotas even after test deletion (a deletion must not refund API calls).
  if exists(select 1 from bot_private.records where account_id=p_account and kind='api_usage') then
    raise exception 'quota-bearing test accounts must be retained for audit';
  end if;
  delete from bot_private.accounts where id=p_account and is_test;
end $$;

revoke all on function public.bot_read(text) from public,anon,authenticated;
revoke all on function public.bot_commit(text,boolean,bigint,jsonb,jsonb) from public,anon,authenticated;
revoke all on function public.bot_reserve_api(text,text,text,text,integer,integer,integer)
  from public,anon,authenticated;
revoke all on function public.bot_delete_test(text) from public,anon,authenticated;
grant execute on function public.bot_read(text),
  public.bot_commit(text,boolean,bigint,jsonb,jsonb),
  public.bot_reserve_api(text,text,text,text,integer,integer,integer),
  public.bot_delete_test(text) to service_role;

-- 20261016000200_public.sql
-- A dedicated read model, never an owner-rights view over internal tables.
create table if not exists public.bot_dashboard (
  id text primary key check (id='paper-live'),
  document jsonb not null,
  published_at timestamptz not null default now()
);
alter table public.bot_dashboard enable row level security;
revoke all on public.bot_dashboard from public,anon,authenticated,service_role;
grant select on public.bot_dashboard to anon,authenticated;
drop policy if exists public_dashboard_read on public.bot_dashboard;
create policy public_dashboard_read on public.bot_dashboard for select to anon,authenticated
  using (id='paper-live');

create or replace function public.bot_publish(p_account text,p_version bigint,p_document jsonb)
returns void language plpgsql security definer set search_path = '' as $$
begin
  perform pg_advisory_xact_lock(490016001);
  if not exists(select 1 from bot_private.accounts where id=p_account and not is_test
    and id='paper-live' and version=p_version) then
    raise exception using errcode='40001',message='publication scope or version mismatch';
  end if;
  if exists(select 1 from jsonb_object_keys(p_document) k
    where k not in ('schema_version','state','updated_at','started_at','summary','series',
      'holdings','trades','decisions','usage','warnings')) or
      (p_document->>'schema_version')::int<>1 then raise exception 'invalid public contract'; end if;
  insert into public.bot_dashboard(id,document) values(p_account,p_document)
    on conflict(id) do update set document=excluded.document,published_at=now();
end $$;
revoke all on function public.bot_publish(text,bigint,jsonb) from public,anon,authenticated;
grant execute on function public.bot_publish(text,bigint,jsonb) to service_role;

notify pgrst, 'reload schema';

-- 20261017000100_operations.sql
-- Additive Phase 5: no existing account/ledger/quota rows are rewritten.
-- Test-only operation controller. All times and fencing decisions use DB time.
-- Private pre-migration snapshots: source rows remain unchanged. Not a substitute
-- for an off-site database backup, but permits before/after integrity comparison.
create table if not exists bot_private.phase5_before_accounts as table bot_private.accounts;
create table if not exists bot_private.phase5_before_records as table bot_private.records;
create table if not exists bot_private.phase5_before_balances as table bot_private.balances;
create table if not exists bot_private.phase5_before_positions as table bot_private.positions;
alter table bot_private.phase5_before_accounts enable row level security;
alter table bot_private.phase5_before_records enable row level security;
alter table bot_private.phase5_before_balances enable row level security;
alter table bot_private.phase5_before_positions enable row level security;
create table if not exists bot_private.operation_runs (
 account text not null check(account ~ '^test-phase5-[a-z0-9-]+$'),
 run_id text not null, token bigint generated always as identity unique,
 owner text not null, lease_until timestamptz not null,
 state text not null default 'RUNNING' check(state in
 ('RUNNING','SUCCEEDED','FAILED','PARTIAL','NEEDS_REVIEW','SKIPPED')),
 stage integer not null default 0 check(stage between 0 and 8),
 metadata jsonb not null, outcome jsonb,
 started_at timestamptz not null default clock_timestamp(),
 updated_at timestamptz not null default clock_timestamp(),
 primary key(account,run_id)
);
create table if not exists bot_private.operation_controls (
 account text primary key check(account ~ '^test-phase5-[a-z0-9-]+$'),
 stopped boolean not null default false, reason text not null default ''
);
create table if not exists bot_private.operation_events (
 id bigint generated always as identity primary key,
 account text not null, run_id text, at timestamptz not null default clock_timestamp(),
 event jsonb not null
);
-- Small test universes: immutable private JSON generations, not public artifacts/cache.
create table if not exists bot_private.operation_data (
 account text not null, key text not null, generation bigint generated always as identity,
 run_id text not null, payload jsonb not null, at timestamptz not null default clock_timestamp(),
 primary key(account,key,generation), check(pg_column_size(payload)<4000000)
);
alter table bot_private.operation_runs enable row level security;
alter table bot_private.operation_controls enable row level security;
alter table bot_private.operation_events enable row level security;
alter table bot_private.operation_data enable row level security;
revoke all on all tables in schema bot_private from public,anon,authenticated,service_role;

create or replace function bot_private.operation_check(p_account text,p_run text,p_token bigint)
returns void language plpgsql security definer set search_path='' as $$
begin
 perform pg_advisory_xact_lock(490016001);
 if p_account !~ '^test-phase5-[a-z0-9-]+$' or not exists(
 select 1 from bot_private.operation_runs where account=p_account and run_id=p_run
 and token=p_token and state='RUNNING' and lease_until>clock_timestamp())
 or exists(select 1 from bot_private.operation_controls where account=p_account and stopped)
 then raise exception 'operation fenced, stopped, expired or unknown'; end if;
end $$;

create or replace function public.bot_operation_claim(p_account text,p_run text,p_owner text,
 p_metadata jsonb,p_seconds integer default 600) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r bot_private.operation_runs;
begin
 perform pg_advisory_xact_lock(490016001);
 if p_account !~ '^test-phase5-[a-z0-9-]+$' or length(p_run)>180 or length(p_owner)>180
 or p_seconds not between 10 and 900 or jsonb_typeof(p_metadata)<>'object'
 then raise exception 'invalid test operation'; end if;
 if exists(select 1 from bot_private.operation_controls where account=p_account and stopped)
 then raise exception 'account stopped'; end if;
 select * into r from bot_private.operation_runs where account=p_account and run_id=p_run;
 if found then
   if r.metadata is distinct from p_metadata then raise exception 'slot configuration changed'; end if;
   if r.state in ('SUCCEEDED','SKIPPED') then return to_jsonb(r); end if;
   raise exception 'existing operation requires inspection; no automatic replay';
 end if;
 if exists(select 1 from bot_private.operation_runs where account=p_account
 and state in ('RUNNING','NEEDS_REVIEW','PARTIAL','FAILED'))
 then raise exception 'unresolved account operation; inspect before continuing'; end if;
 insert into bot_private.operation_runs(account,run_id,owner,lease_until,metadata)
 values(p_account,p_run,p_owner,clock_timestamp()+make_interval(secs=>p_seconds),p_metadata)
 returning * into r;
 return to_jsonb(r);
end $$;

create or replace function public.bot_operation_step(p_account text,p_run text,p_token bigint,
 p_stage integer,p_state text default 'RUNNING',p_outcome jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r bot_private.operation_runs;
begin
 perform bot_private.operation_check(p_account,p_run,p_token);
 select * into r from bot_private.operation_runs where account=p_account and run_id=p_run;
 if p_stage<r.stage or p_stage>r.stage+1 or p_stage>8
 or p_state not in ('RUNNING','SUCCEEDED','FAILED','PARTIAL','NEEDS_REVIEW','SKIPPED')
 or (p_state='SUCCEEDED' and p_stage<>8) then raise exception 'invalid operation transition'; end if;
 update bot_private.operation_runs set stage=p_stage,state=p_state,outcome=p_outcome,
 updated_at=clock_timestamp(),lease_until=clock_timestamp()+interval '600 seconds'
 where account=p_account and run_id=p_run returning * into r;
 insert into bot_private.operation_events(account,run_id,event)
 values(p_account,p_run,jsonb_build_object('stage',p_stage,'state',p_state,'outcome',p_outcome));
 return to_jsonb(r);
end $$;

create or replace function public.bot_operation_read(p_account text) returns jsonb
language plpgsql security definer set search_path='' as $$
begin
 if p_account !~ '^test-phase5-[a-z0-9-]+$' then raise exception 'test scope required'; end if;
 return jsonb_build_object('runs',coalesce((select jsonb_agg(to_jsonb(r) order by token)
 from bot_private.operation_runs r where account=p_account),'[]'::jsonb),
 'stopped',coalesce((select stopped from bot_private.operation_controls where account=p_account),false),
 'data',coalesce((select jsonb_object_agg(key,payload) from (
 select distinct on (key) key,payload from bot_private.operation_data where account=p_account
 order by key,generation desc) d),'{}'::jsonb));
end $$;

-- Reconciliation closes an uncertain attempt, never replays it or refunds quota.
-- A fresh future slot may run only after explicit reviewed closure. No trading mutations here.
create or replace function public.bot_operation_review(p_account text,p_run text,p_reason text,
 p_stop boolean default true) returns void
language plpgsql security definer set search_path='' as $$
begin
 perform pg_advisory_xact_lock(490016001);
 if p_account !~ '^test-phase5-[a-z0-9-]+$' or length(trim(p_reason))<12
 then raise exception 'test scope and review reason required'; end if;
 if not p_stop and exists(select 1 from bot_private.operation_runs where account=p_account and state='RUNNING'
 and lease_until>clock_timestamp()) then raise exception 'active runner must finish or expire'; end if;
 update bot_private.operation_runs set state=case when p_stop then 'NEEDS_REVIEW' else 'SKIPPED' end,updated_at=clock_timestamp()
 where account=p_account and run_id=p_run and state in ('RUNNING','NEEDS_REVIEW','FAILED','PARTIAL');
 insert into bot_private.operation_controls values(p_account,p_stop,p_reason)
 on conflict(account) do update set stopped=excluded.stopped,reason=excluded.reason;
 insert into bot_private.operation_events(account,run_id,event)
 values(p_account,p_run,jsonb_build_object('review_reason',p_reason,'stopped',p_stop));
end $$;

-- Mandatory guards also cover legacy RPCs and account deletion: no bypass through old CLI.
create or replace function bot_private.operation_guard() returns trigger
language plpgsql security definer set search_path='' as $$
declare a text; v jsonb;
begin
 v:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
 a:=case when tg_table_name='accounts' then v->>'id' else v->>'account_id' end;
 if a like 'test-phase5-%' then
   if tg_op='DELETE' then raise exception 'operation accounts retain audit history'; end if;
   perform bot_private.operation_check(a,current_setting('bot.operation_run',true),
     nullif(current_setting('bot.operation_token',true),'')::bigint);
 elsif a='paper-live' then
   if tg_table_name='records' and v->>'kind' in ('orders','executions','fx_exchanges','cash_ledger')
   and not (v->>'kind'='cash_ledger' and v->'payload'->>'kind'='INITIAL'
     and not exists(select 1 from bot_private.accounts where id=a and value is not null))
   then raise exception 'paper-live financial mutations disabled'; end if;
   if tg_table_name='accounts' and tg_op='UPDATE'
   and to_jsonb(old)->'value' <> 'null'::jsonb and (
    to_jsonb(old)->'value'->'balances' is distinct from v->'value'->'balances' or
    to_jsonb(old)->'value'->'positions' is distinct from v->'value'->'positions' or
    to_jsonb(old)->'value'->'initial_jpy' is distinct from v->'value'->'initial_jpy')
   then raise exception 'paper-live financial mutations disabled'; end if;
 end if;
 if tg_op='DELETE' then return old; end if; return new;
end $$;
drop trigger if exists operation_guard on bot_private.accounts;
create trigger operation_guard before insert or update or delete on bot_private.accounts
for each row execute function bot_private.operation_guard();
drop trigger if exists operation_guard on bot_private.records;
create trigger operation_guard before insert or update or delete on bot_private.records
for each row execute function bot_private.operation_guard();

create or replace function public.bot_operation_commit(p_account text,p_run text,p_token bigint,
 p_test boolean,p_version bigint,p_value jsonb,p_writes jsonb) returns bigint
language plpgsql security definer set search_path='' as $$
declare v bigint;
begin
 perform bot_private.operation_check(p_account,p_run,p_token);
 perform set_config('bot.operation_run',p_run,true);
 perform set_config('bot.operation_token',p_token::text,true);
 v:=public.bot_commit(p_account,p_test,p_version,p_value,p_writes);
 perform bot_private.operation_check(p_account,p_run,p_token);
 return v;
end $$;
create or replace function public.bot_operation_reserve(p_account text,p_run text,p_token bigint,
 p_decision text,p_request text,p_model text,p_day_limit integer,p_month_limit integer,p_run_limit integer)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v jsonb;
begin
 perform bot_private.operation_check(p_account,p_run,p_token);
 perform set_config('bot.operation_run',p_run,true);
 perform set_config('bot.operation_token',p_token::text,true);
 v:=public.bot_reserve_api(p_account,p_decision,p_request,p_model,p_day_limit,p_month_limit,p_run_limit);
 perform bot_private.operation_check(p_account,p_run,p_token);
 return v;
end $$;
create or replace function public.bot_operation_data(p_account text,p_run text,p_token bigint,
 p_key text,p_payload jsonb) returns void
language plpgsql security definer set search_path='' as $$
begin
 perform bot_private.operation_check(p_account,p_run,p_token);
 if length(p_key)>160 or pg_column_size(p_payload)>4000000 then raise exception 'data limit'; end if;
 insert into bot_private.operation_data(account,key,run_id,payload) values(p_account,p_key,p_run,p_payload);
end $$;

revoke all on all functions in schema bot_private from public,anon,authenticated,service_role;
revoke all on function public.bot_operation_claim(text,text,text,jsonb,integer),
 public.bot_operation_step(text,text,bigint,integer,text,jsonb), public.bot_operation_read(text),
 public.bot_operation_review(text,text,text,boolean),
 public.bot_operation_commit(text,text,bigint,boolean,bigint,jsonb,jsonb),
 public.bot_operation_reserve(text,text,bigint,text,text,text,integer,integer,integer),
 public.bot_operation_data(text,text,bigint,text,jsonb) from public,anon,authenticated;
grant execute on function public.bot_operation_claim(text,text,text,jsonb,integer),
 public.bot_operation_step(text,text,bigint,integer,text,jsonb), public.bot_operation_read(text),
 public.bot_operation_review(text,text,text,boolean),
 public.bot_operation_commit(text,text,bigint,boolean,bigint,jsonb,jsonb),
 public.bot_operation_reserve(text,text,bigint,text,text,text,integer,integer,integer),
 public.bot_operation_data(text,text,bigint,text,jsonb) to service_role;

-- Only a boolean leaves the server; source account/history/usage payloads stay private.
create or replace function public.bot_operation_preserved() returns boolean
language sql stable security definer set search_path='' as $$
 select not exists(select 1 from bot_private.phase5_before_accounts b
   left join bot_private.accounts a on a.id=b.id where to_jsonb(a) is distinct from to_jsonb(b))
 and not exists(select 1 from bot_private.phase5_before_records b
   left join bot_private.records a on (a.account_id,a.kind,a.key)=(b.account_id,b.kind,b.key)
   where to_jsonb(a) is distinct from to_jsonb(b))
 and not exists(select 1 from bot_private.phase5_before_balances b
   left join bot_private.balances a on (a.account_id,a.currency)=(b.account_id,b.currency)
   where to_jsonb(a) is distinct from to_jsonb(b))
 and not exists(select 1 from bot_private.phase5_before_positions b
   left join bot_private.positions a on (a.account_id,a.symbol)=(b.account_id,b.symbol)
   where to_jsonb(a) is distinct from to_jsonb(b))
$$;
revoke all on function public.bot_operation_preserved() from public,anon,authenticated;
grant execute on function public.bot_operation_preserved() to service_role;
notify pgrst,'reload schema';

COMMIT;
